action.command:
cd /workspace/project && curl -s --max-time 30 "https://resifactory.net/products/residential" -o /tmp/res.html -w "HTTP %{http_code}\n"; python3 - <<'EOF'
import re,html
t=open('/tmp/res.html',errors='ignore').read()
for kw in ['sticky','session','~','username','format']:
    for m in re.finditer(kw,t,re.I):
        s=max(0,m.start()-150); frag=re.sub(r'<[^>]+>',' ',t[s:m.start()+220])
        frag=html.unescape(re.sub(r'\s+',' ',frag)).strip()
        if len(frag)>60: print(f"[{kw}] {frag[:240]}\n")
EOF

